// src/ui/drawer.js
// Generic flyout drawer utility for reuse

export class Drawer {
  static _instances = [];
  /**
  // Registry to track all Drawer instances
  Drawer._instances = [];
   * @param {Object} options
   * @param {string} options.id - Unique id for the drawer DOM element
   * @param {string} options.header - Drawer header text or HTML
   * @param {string|HTMLElement} options.content - Drawer content (element or selector or HTML)
   * @param {HTMLElement} options.triggerEl - The element that triggers the drawer (e.g., sidebar icon)
   * @param {string} [options.position='right'] - Drawer position (right/left)
   * @param {boolean} [options.sticky=false] - If true, click toggles sticky open/close
   */
  constructor({
    id,
    header,
    content,
    triggerEl,
    position = "right",
    sticky = false,
  }) {
    this.id = id;
    this.header = header;
    this.content = content;
    this.triggerEl = triggerEl;
    this.position = position;
    this.sticky = sticky;
    this.stickyOpen = false;
    this.flyoutTimer = null;
    this.drawer = this._createDrawer();
    // Ensure static property exists for environments that don't support class fields
    if (!Drawer._instances) Drawer._instances = [];
    Drawer._instances.push(this);
    this._attachEvents();
  }

  _createDrawer() {
    let drawer = document.getElementById(this.id);
    if (!drawer) {
      drawer = document.createElement("div");
      drawer.id = this.id;
      drawer.className = `sidebar-flyout-drawer ${this.position}`;
      drawer.innerHTML = `
        <div class="sidebar-flyout-header">${this.header}</div>
        <div class="sidebar-flyout-content"></div>
      `;
      document.body.appendChild(drawer);
    }
    // Set content
    const contentEl = drawer.querySelector(".sidebar-flyout-content");
    if (typeof this.content === "string") {
      // If selector, try to move element
      if (this.content.startsWith("#") || this.content.startsWith(".")) {
        const el = document.querySelector(this.content);
        if (el) contentEl.appendChild(el);
        else contentEl.innerHTML = "";
      } else {
        contentEl.innerHTML = this.content;
      }
    } else if (this.content instanceof HTMLElement) {
      contentEl.appendChild(this.content);
    }
    return drawer;
  }

  _attachEvents() {
    const drawer = this.drawer;
    const iconEl = this.triggerEl;
    const self = this;
    function openFlyout() {
      // Prevent hover open if any sticky drawer is open
      const anyStickyOpen = Drawer._instances.some(
        (inst) => inst.sticky && inst.stickyOpen,
      );
      if (!self.stickyOpen && anyStickyOpen) return;
      clearTimeout(self.flyoutTimer);
      // Close all other sticky drawers
      Drawer._instances.forEach((inst) => {
        if (inst !== self && inst.sticky && inst.stickyOpen) {
          inst.stickyOpen = false;
          inst.drawer.classList.remove("open");
          if (inst.triggerEl) inst.triggerEl.classList.remove("active");
        }
      });
      // Position drawer as a floating window anchored to the trigger element
      try {
        drawer.classList.add("floating");
        drawer.style.position = "fixed";
        // reset inline position to compute natural size
        drawer.style.left = "";
        drawer.style.top = "";
        drawer.style.right = "";
        drawer.style.bottom = "";
        // allow browser to compute sizes
        const rect = iconEl.getBoundingClientRect();
        const dw = drawer.offsetWidth || 320;
        const dh = drawer.offsetHeight || 220;
        // Prefer placing to the right of trigger; if not enough space, place above.
        const spaceRight = window.innerWidth - rect.right;
        if (spaceRight > dw + 12) {
          drawer.style.left = rect.right + 12 + "px";
          drawer.style.top = Math.max(8, rect.top - 8) + "px";
        } else {
          // place above centered on trigger
          const left = Math.max(8, rect.left + rect.width / 2 - dw / 2);
          drawer.style.left = left + "px";
          drawer.style.top = Math.max(8, rect.top - dh - 12) + "px";
        }
      } catch (e) {
        // fallback to default behavior
      }
      // show
      drawer.classList.add("open");
      iconEl.classList.add("active");
    }
    function closeFlyout() {
      self.flyoutTimer = setTimeout(() => {
        if (!self.stickyOpen) {
          drawer.classList.remove("open");
          iconEl.classList.remove("active");
        }
      }, 120);
    }
    iconEl.addEventListener("mouseenter", openFlyout);
    iconEl.addEventListener("mouseleave", closeFlyout);
    drawer.addEventListener("mouseenter", openFlyout);
    drawer.addEventListener("mouseleave", closeFlyout);
    iconEl.addEventListener("click", () => {
      if (!self.sticky) return;
      self.stickyOpen = !self.stickyOpen;
      if (self.stickyOpen) {
        openFlyout();
      } else {
        drawer.classList.remove("open");
        iconEl.classList.remove("active");
      }
    });
  }

  get element() {
    return this.drawer;
  }
}
