// Response layer color filter: allows showing only pixels that map to a specific color
let _responseColorFilterHex = null;
function normalizeToHex(col) {
  if (!col && col !== 0) return null;
  if (Array.isArray(col)) {
    // [r,g,b,a]
    const r = Number(col[0]) || 0;
    const g = Number(col[1]) || 0;
    const b = Number(col[2]) || 0;
    return (
      "#" + [r, g, b].map((v) => Number(v).toString(16).padStart(2, "0")).join("")
    ).toLowerCase();
  }
  const s = String(col).trim();
  // Accept with or without leading '#'
  if (s.startsWith("#") || /^[0-9a-fA-F]{6}$/.test(s) || /^[0-9a-fA-F]{3}$/.test(s)) {
    const h = s.startsWith("#") ? s.substring(1) : s;
    if (h.length === 3) {
      return ("#" + h.split("").map((c) => c + c).join("")).toLowerCase();
    }
    return ("#" + h.substring(0, 6)).toLowerCase();
  }
  const rgbaMatch = s.match(/rgba?\s*\(([^)]+)\)/i);
  if (rgbaMatch) {
    const parts = rgbaMatch[1].split(",").map((p) => p.trim());
    const r = Number(parts[0]) || 0;
    const g = Number(parts[1]) || 0;
    const b = Number(parts[2]) || 0;
    return (
      "#" + [r, g, b].map((v) => Number(v).toString(16).padStart(2, "0")).join("")
    ).toLowerCase();
  }
  return null;
}

function setResponseColorFilter(hexOrColor) {
  const h = normalizeToHex(hexOrColor);
    // If caller passed null/undefined, treat that as "no filter" (show all colors)
    if (hexOrColor === null || hexOrColor === undefined) {
      _responseColorFilterHex = null;
      try { console.log("Response color filter cleared (show all colors)"); } catch (e) {}
      try {
         redrawResponseFromCache(); } catch (e) {}
      return;
    }

    let final = h;
    if (!final) {
      try {
        const rgba = parseColorToRgba(hexOrColor);
        final = ("#" + [rgba[0], rgba[1], rgba[2]].map((v) => Number(v).toString(16).padStart(2, "0")).join("")).toLowerCase();
      } catch (e) {
        final = null;
      }
    }
    _responseColorFilterHex = final;
  try {
    console.log("Response color filter set:", hexOrColor, "=>", final);
  } catch (e) {}
  try {
    redrawResponseFromCache();
  } catch (e) {}
}
window.setResponseColorFilter = setResponseColorFilter;
