// Parse color to RGBA array (top-level so reusable)
function parseColorToRgba(col) {
  if (!col && col !== 0) return [0, 0, 0, 0];
  if (Array.isArray(col)) {
    const [r = 0, g = 0, b = 0, a = 255] = col;
    return [r, g, b, a];
  }
  const s = String(col).trim();
  if (s.startsWith("#")) {
    const h = s.substring(1);
    const rr = parseInt(h.substring(0, 2), 16) || 0;
    const gg = parseInt(h.substring(2, 4), 16) || 0;
    const bb = parseInt(h.substring(4, 6), 16) || 0;
    return [rr, gg, bb, 255];
  }
  const rgbaMatch = s.match(/rgba?\s*\(([^)]+)\)/i);
  if (rgbaMatch) {
    const parts = rgbaMatch[1].split(",").map((p) => p.trim());
    const r = Number(parts[0]) || 0;
    const g = Number(parts[1]) || 0;
    const b = Number(parts[2]) || 0;
    let a = 255;
    if (parts[3] !== undefined) {
      const aval = Number(parts[3]);
      if (!Number.isNaN(aval)) a = Math.round(aval <= 1 ? aval * 255 : aval);
    }
    return [r, g, b, a];
  }
  return [0, 0, 0, 0];
}

// Redraw response layer from cached warp result when filter changes
function redrawResponseFromCache() {
  try {
    if (!_lastWarped || !_lastWarped.data || !_lastWarped.data[0]) return;
    const warped = _lastWarped;
    const res = _lastRes || {};
    const gwOpts = _lastGwOpts || {};
    const outW = warped.out_width || res.width;
    const outH = warped.out_height || res.height;
    const band = warped.data[0];
    const tmpCanvas = document.createElement("canvas");
    tmpCanvas.width = outW;
    tmpCanvas.height = outH;
    const ctx = tmpCanvas.getContext("2d");
    const img = ctx.createImageData(outW, outH);
    for (let i = 0, p = 0; i < band.length && p < img.data.length; i++, p += 4) {
      const raw = band[i];
      const vnum = raw === null || raw === undefined ? NaN : Number(raw);
      const isNoData = Number.isNaN(vnum) || (typeof gwOpts !== 'undefined' && raw === gwOpts.out_no_data);
      if (isNoData) {
        img.data[p] = 0; img.data[p+1] = 0; img.data[p+2] = 0; img.data[p+3] = 0; continue;
      }
      const v = Math.round(vnum);
      let colorVal = classColorMap[v] || null;
      if (!colorVal) {
        const pal = paletteArray && paletteArray.length > v ? paletteArray[v] : null;
        colorVal = pal || null;
      }
      if (colorVal) {
        const colorHex = normalizeToHex(colorVal);
        if (_responseColorFilterHex && colorHex !== _responseColorFilterHex) {
          img.data[p] = 0; img.data[p+1] = 0; img.data[p+2] = 0; img.data[p+3] = 0;
        } else {
          const rgba = parseColorToRgba(colorVal);
          img.data[p] = rgba[0]; img.data[p+1] = rgba[1]; img.data[p+2] = rgba[2]; img.data[p+3] = rgba[3];
        }
      } else {
        img.data[p] = 0; img.data[p+1] = 0; img.data[p+2] = 0; img.data[p+3] = 0;
      }
    }
    ctx.putImageData(img, 0, 0);
    const dataUrl = tmpCanvas.toDataURL("image/png");
    const imageExtent = warped.out_bbox || (res && res.actualRasterBBox);
    const imgSrc = new ImageStatic({ url: dataUrl, imageExtent: imageExtent, projection: "EPSG:3857" });
    const imgLayer = new ImageLayer({ source: imgSrc });
    if (responseGroup && responseGroup.getLayers) {
      const layersCol = responseGroup.getLayers();
      layersCol.clear();
       if (_currentResponseLayer) layersCol.push(imgLayer);
    } else {
      if (_currentResponseLayer) { try { map.removeLayer(_currentResponseLayer); } catch (e) {} _currentResponseLayer = null; }
      map.addLayer(imgLayer);
    }
    _currentResponseLayer = imgLayer;
  } catch (e) {
    console.warn("redrawResponseFromCache failed:", e);
  }
}

